custom_qss:
/* ============================================================
   ZAFFRE — instrument panel.
   One cool hue: steel cyan on blue-charcoal. Everything else is
   desaturated slate. Identity is carried by typography and
   structure, not color: Segoe UI body, Cascadia Code on technical
   values, uppercase letter-spaced labels, thin 1px rules, left
   tick-mark accent bars. Vertical light-falloff only.
   ============================================================ */

/* ---------- base type ---------- */
* {
    font-family: Segoe UI, Calibri, Ubuntu, sans-serif;
    color: #e4e9ee;
}
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent;
    border: none;
}

/* ---------- window: near-flat charcoal, cool top hairline ---------- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #11151a, stop:1 #0c0f12) !important;
    border-top: 1px solid #2c3640;
}
QDialog {
    background: #0c0f12 !important;
    border: 1px solid #1f262d;
    border-top: 1px solid #5eb8d6;
}

/* ---------- menubar: flat strip, cyan active item ---------- */
QMenuBar {
    background: #0a0d10 !important;
    border-bottom: 1px solid #1f262d;
    padding: 2px 0;
}
QMenuBar::item {
    background: transparent;
    color: #aab6c2;
    padding: 5px 12px;
    font-size: 12px;
    letter-spacing: 0.3px;
}
QMenuBar::item:selected {
    background: #161b21;
    color: #a8dcea;
}

/* ---------- popup menus: clean, mono-ish values ---------- */
QMenu {
    background: #11151a !important;
    border: 1px solid #2c3640;
    padding: 4px;
    font-size: 12px;
}
QMenu::item {
    padding: 6px 28px 6px 16px;
    border-radius: 3px;
    color: #e4e9ee;
    background: transparent;
}
QMenu::item:selected {
    background: #161b21;
    color: #a8dcea;
}
QMenu::item:disabled {
    color: #4a5560;
}
QMenu::separator {
    height: 1px;
    background: #1f262d;
    margin: 5px 10px;
}
QMenu::indicator {
    width: 12px;
    height: 12px;
    margin-left: 6px;
}

/* ---------- toolbar: flat, hairline under, cyan active ---------- */
QToolBar {
    background: #0a0d10 !important;
    border-bottom: 1px solid #1f262d;
    spacing: 4px;
    padding: 4px;
}
QToolBar::separator {
    background: #1f262d;
    width: 1px;
    margin: 6px 4px;
}
QToolBar::handle {
    background: #2c3640;
    width: 8px;
}
QToolBar QToolButton {
    background: transparent;
    border: 1px solid transparent;
    border-radius: 4px;
    padding: 5px 9px;
    color: #aab6c2;
    font-size: 12px;
}
QToolBar QToolButton:hover {
    background: #161b21;
    border: 1px solid #2c3640;
    color: #a8dcea;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: #080a0d;
    border: 1px solid #5eb8d6;
    color: #a8dcea;
}

/* ---------- buttons: quiet raised, cyan border on hover ---------- */
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #11151a, stop:1 #0a0d10) !important;
    border: 1px solid #1f262d;
    border-radius: 4px;
    padding: 6px 18px;
    color: #e4e9ee;
    font-size: 12px;
    font-weight: 500;
}
QPushButton:hover {
    border: 1px solid #5eb8d6;
    color: #a8dcea;
}
QPushButton:pressed {
    background: #080a0d !important;
    color: #a8dcea;
}
QPushButton:checked {
    background: #080a0d !important;
    border: 1px solid #5eb8d6;
    color: #a8dcea;
}
QPushButton:default {
    border: 1px solid #5eb8d6;
}
QPushButton:disabled {
    color: #4a5560;
    border: 1px solid #1f262d;
}
QPushButton:focus {
    outline: none;
}

/* ---------- inputs: recessed wells, cyan focus ---------- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #080a0d !important;
    border: 1px solid #1f262d;
    border-radius: 4px;
    padding: 5px 8px;
    color: #e4e9ee;
    font-family: Cascadia Code, Consolas, monospace;
    font-size: 12px;
    selection-background-color: #2a6b82;
    selection-color: #e4e9ee;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus,
QTextEdit:focus, QPlainTextEdit:focus {
    border: 1px solid #5eb8d6;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #4a5560;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent;
    border: none;
    width: 14px;
}
QSpinBox::up-arrow, QSpinBox::down-arrow {
    width: 7px;
    height: 7px;
}

QComboBox {
    background: #080a0d !important;
    border: 1px solid #1f262d;
    border-radius: 4px;
    padding: 5px 8px;
    color: #e4e9ee;
    font-size: 12px;
}
QComboBox:hover {
    border: 1px solid #2c3640;
}
QComboBox:focus {
    border: 1px solid #5eb8d6;
}
QComboBox::drop-down {
    border: none;
    background: transparent;
    width: 16px;
}
QComboBox::down-arrow {
    width: 8px;
    height: 8px;
}
QComboBox QAbstractItemView {
    background: #11151a !important;
    border: 1px solid #2c3640;
    selection-background-color: #161b21;
    selection-color: #a8dcea;
    outline: none;
}
QComboBox:disabled {
    color: #4a5560;
}

/* ---------- checkboxes: cyan check ---------- */
QCheckBox, QRadioButton {
    background: transparent;
    color: #e4e9ee;
    spacing: 7px;
    font-size: 12px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 14px;
    height: 14px;
    background: #080a0d;
    border: 1px solid #2c3640;
    border-radius: 3px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    border: 1px solid #5eb8d6;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: #5eb8d6;
    border: 1px solid #5eb8d6;
}

/* ---------- tabs: cyan underline on selected ---------- */
QTabBar::tab {
    background: transparent;
    color: #7b8794;
    padding: 8px 16px;
    border: none;
    border-bottom: 2px solid transparent;
    font-size: 12px;
    letter-spacing: 0.4px;
}
QTabBar::tab:hover {
    color: #e4e9ee;
}
QTabBar::tab:selected {
    color: #a8dcea;
    border-bottom: 2px solid #5eb8d6;
}
QTabWidget::pane {
    border: none;
    border-top: 1px solid #1f262d;
    background: #0c0f12;
}

/* ---------- docks: flat panels, cyan hairline under title ---------- */
QDockWidget {
    background: #11151a !important;
    border: 1px solid #1f262d;
    titlebar-close-icon: none;
    titlebar-normal-icon: none;
}
QDockWidget::title {
    background: #0a0d10 !important;
    border-bottom: 1px solid #1f262d;
    padding: 6px 10px;
    color: #aab6c2;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1.2px;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent;
    border: none;
    border-radius: 3px;
    padding: 2px;
    icon-size: 12px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: #161b21;
}

/* ---------- group boxes: uppercase cyan label, left tick mark ---------- */
QGroupBox {
    background: transparent;
    border: 1px solid #1f262d;
    border-left: 2px solid #2a6b82;
    border-radius: 4px;
    margin-top: 12px;
    padding-top: 10px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1px;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 8px;
    color: #5eb8d6;
    background: #0c0f12;
}

/* ---------- item views: clean list, cyan selected ---------- */
QAbstractItemView {
    background: #080a0d !important;
    border: 1px solid #1f262d;
    border-radius: 4px;
    alternate-background-color: #0a0d10;
    outline: none;
    selection-background-color: #161b21;
    selection-color: #a8dcea;
    font-size: 12px;
}
QAbstractItemView::item {
    padding: 5px 8px;
    border: none;
    color: #e4e9ee;
}
QAbstractItemView::item:hover {
    background: #161b21;
}
QAbstractItemView::item:selected {
    background: #161b21;
    color: #a8dcea;
    border-left: 2px solid #5eb8d6;
}
QAbstractItemView::item:selected:!active {
    background: #0a0d10;
    color: #aab6c2;
}
QTreeView::branch {
    background: transparent;
}
QHeaderView::section {
    background: #0a0d10 !important;
    border: none;
    border-bottom: 1px solid #2c3640;
    border-right: 1px solid #1f262d;
    padding: 6px 10px;
    color: #7b8794;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.8px;
}

/* ---------- scrollbars: thin, cyan handle ---------- */
QScrollBar:vertical {
    background: #080a0d;
    width: 10px;
    margin: 0;
    border: none;
}
QScrollBar::handle:vertical {
    background: #2c3640;
    border-radius: 5px;
    min-height: 30px;
}
QScrollBar::handle:vertical:hover {
    background: #2a6b82;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    border: none;
    background: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: none;
}
QScrollBar:horizontal {
    background: #080a0d;
    height: 10px;
    margin: 0;
    border: none;
}
QScrollBar::handle:horizontal {
    background: #2c3640;
    border-radius: 5px;
    min-width: 30px;
}
QScrollBar::handle:horizontal:hover {
    background: #2a6b82;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    border: none;
    background: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: none;
}
QScrollBar::corner {
    background: none;
}

/* ---------- sliders: cyan fill, ice handle ---------- */
QSlider::groove:horizontal {
    background: #080a0d;
    border: 1px solid #1f262d;
    height: 4px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background: #5eb8d6;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background: #080a0d;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #a8dcea;
    width: 12px;
    height: 12px;
    margin: -5px 0;
    border: 1px solid #5eb8d6;
    border-radius: 7px;
}
QSlider::handle:horizontal:hover {
    background: #ffffff;
    border: 1px solid #a8dcea;
}
QSlider::groove:vertical {
    background: #080a0d;
    border: 1px solid #1f262d;
    width: 4px;
    border-radius: 2px;
}
QSlider::sub-page:vertical {
    background: #5eb8d6;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background: #a8dcea;
    width: 12px;
    height: 12px;
    margin: 0 -5px;
    border: 1px solid #5eb8d6;
    border-radius: 7px;
}

/* ---------- progress: thin cyan fill ---------- */
QProgressBar {
    background: #080a0d;
    border: 1px solid #1f262d;
    border-radius: 3px;
    text-align: center;
    color: #aab6c2;
    font-size: 11px;
    min-height: 14px;
}
QProgressBar::chunk {
    background: #5eb8d6;
    border-radius: 2px;
}

/* ---------- statusbar: flat, dim ---------- */
QStatusBar {
    background: #0a0d10 !important;
    border-top: 1px solid #1f262d;
    color: #7b8794;
    font-size: 11px;
}
QStatusBar::item {
    border: none;
}
QStatusBar QLabel {
    color: #7b8794;
    font-size: 11px;
}

/* ---------- tooltip: clean card ---------- */
QToolTip {
    background: #11151a !important;
    border: 1px solid #2c3640;
    border-radius: 4px;
    padding: 6px 10px;
    color: #e4e9ee;
    font-size: 12px;
}

/* ---------- splitters: hairline, cyan on hover ---------- */
QSplitter::handle {
    background: #1f262d;
}
QSplitter::handle:hover {
    background: #2a6b82;
}

/* ---------- secondary list widgets ---------- */
QListView, QListWidget, QTreeWidget, QTableWidget {
    background: #080a0d !important;
    border: 1px solid #1f262d;
    border-radius: 4px;
    outline: none;
}
QTableCornerButton::section {
    background: #0a0d10;
    border: 1px solid #1f262d;
}
